static Project playlistGroupFixture(){auto p=emptyProject();p.bpm=120;p.songMode=true;p.loop=false;p.patterns[0].length=4;p.patterns[0].lanes[0]={{0,.25,36,.8f}};p.patterns[0].lanes[7]={{0,1,60,.8f}};p.clips={{0,0,0,4},{7,0,0,4},{0,0,4,4},{7,0,4,4}};Clip audio;audio.track=2;audio.beat=8;audio.length=4;audio.audioPath="group-source.wav";audio.sourceOffset=.1;audio.gain=.8f;audio.fadeIn=.5;audio.fadeOut=.25;p.clips.push_back(audio);Clip automation;automation.track=3;automation.beat=8;automation.length=4;automation.automationTarget=1;automation.automationTrack=7;automation.points={{0,.2f,false},{2,.9f,true},{4,.4f,false}};p.clips.push_back(automation);p.markers={{"opening","Opening",0,8,2}};ensurePlaylistEditorIds(p);return p;}
static void testPlaylistGroups(const File& root,Assets& assets){
    auto source=playlistGroupFixture();auto original=JSON::toString(projectToJson(source));std::set<int> all={0,1,2,3,4,5};PlaylistGroupStats stats;expect(inspectPlaylistGroup(source,all,stats).wasOk()&&stats.start==0&&stats.end==12&&stats.lowTrack==0&&stats.highTrack==7,"Playlist group bounds include every clip type and lane");Project out;expect(transformPlaylistGroup(source,all,8,0,false,true,out,&stats).wasOk()&&out.clips.size()==6&&stats.resultIndices==std::vector<int>({0,1,2,3,4,5}),"select-all group move shifts arrangement without creating extra clips");bool uniform=true,identities=true;for(int i:all){uniform&=out.clips[(size_t)i].beat==source.clips[(size_t)i].beat+8&&out.clips[(size_t)i].track==source.clips[(size_t)i].track;identities&=out.clips[(size_t)i].editorId==source.clips[(size_t)i].editorId;}expect(uniform&&identities,"group move preserves uniform spacing lanes and editor identities");expect(out.clips[4].sourceOffset==.1&&out.clips[4].fadeIn==.5&&out.clips[4].fadeOut==.25&&out.clips[4].gain==.8f&&out.clips[5].automationTrack==7&&out.clips[5].points[1].hold,"moving mixed clips preserves audio offsets/fades and automation links/curves");expect(JSON::toString(projectToJson(source))==original&&out.markers[0].beat==0&&out.markers[0].endBeat==8&&out.patterns[0].lanes==source.patterns[0].lanes,"group edit preserves source project patterns and marker positions");
    auto shifted=out;expect(transformPlaylistGroup(shifted,{2,3},-12,0,true,false,out,&stats).wasOk()&&out.clips.size()==8&&out.clips[6].beat==0&&out.clips[7].beat==0&&out.clips[2].beat==12,"copy a later song part into newly freed opening space");expect(out.clips[6].pattern==out.clips[2].pattern&&out.clips[6].editorId!=out.clips[2].editorId,"group copies retain shared pattern links but receive independent selection identities");
    expect(transformPlaylistGroup(source,{4,5},8,0,true,true,out,&stats).wasOk()&&out.clips[6].isAudio()&&out.clips[7].isAutomation(),"group copy handles audio and automation together");out.clips[7].points[1].value=.1f;expect(source.clips[5].points[1].value==.9f,"copied automation point vectors are independent");
    Project sentinel=emptyProject();sentinel.title="Unchanged";auto token=JSON::toString(projectToJson(sentinel));auto rejected=[&](const std::set<int>& indices,double delta,int tracks,bool copy,bool overlap){return transformPlaylistGroup(source,indices,delta,tracks,copy,overlap,sentinel).failed()&&JSON::toString(projectToJson(sentinel))==token;};expect(rejected({},4,0,true,true)&&rejected({-1},4,0,true,true)&&rejected({6},4,0,true,true),"empty stale or invalid group selections reject atomically");expect(rejected(all,-.25,0,false,true)&&rejected(all,4088,0,false,true)&&rejected(all,0,-1,false,true)&&rejected(all,0,1,false,true)&&rejected(all,std::nan(""),0,false,true),"time/lane bounds reject a whole group without cropping or partial moves");expect(rejected({0,1},4,0,false,false),"explicit no-overlap move rejects destination blocks on shared lanes");expect(transformPlaylistGroup(source,{0,1},4,0,false,true,out).wasOk()&&out.clips[0].beat==4,"explicit layering preserves destination clips");
    auto automation=source;Clip linked=source.clips[5];linked.track=6;linked.beat=16;automation.clips.push_back(linked);expect(transformPlaylistGroup(automation,{5},8,0,true,false,sentinel).failed(),"no-overlap policy includes automation parameters linked from another lane");
    auto full=source;while(full.clips.size()<maxClips)full.clips.push_back(full.clips.front());expect(transformPlaylistGroup(full,{0},4,0,true,true,sentinel).failed()&&transformPlaylistGroup(full,all,4,0,false,true,out).wasOk(),"copy enforces clip capacity while group moves work at full capacity");auto automated=source;automated.clips.clear();for(int i=0;i<maxAutomationClips;++i){auto c=source.clips[5];c.beat=i*4;automated.clips.push_back(c);}expect(transformPlaylistGroup(automated,{0},300,0,true,true,sentinel).failed(),"group copy enforces total automation clip capacity");
    auto manyPoints=source;manyPoints.clips.clear();for(int i=0;i<16;++i){auto c=source.clips[5];c.points.clear();for(int n=0;n<256;++n)c.points.push_back({n/64.,.5f,false});c.beat=i*4;manyPoints.clips.push_back(c);}expect(transformPlaylistGroup(manyPoints,{0},200,0,true,true,sentinel).failed(),"group copy enforces aggregate automation point capacity");
    expect(deletePlaylistGroup(source,{1,4},out).wasOk()&&out.clips.size()==4&&out.clips[0].editorId==source.clips[0].editorId&&out.clips[1].editorId==source.clips[2].editorId,"group delete removes only selected indices without shifting other identities");expect(deletePlaylistGroup(source,all,out).wasOk()&&out.clips.empty()&&out.patterns[0].lanes==source.patterns[0].lanes,"delete-all removes Playlist placements and retains the pattern bank");
    expect(insertPlaylistGroup(source,{source.clips[4],source.clips[5]},8,0,true,out,&stats).wasOk()&&stats.resultIndices.size()==2&&out.clips.size()==8,"group clipboard insertion publishes all payload clips together");auto bad=source.clips[0];bad.pattern=999;expect(insertPlaylistGroup(source,{source.clips[4],bad},16,0,true,sentinel).failed()&&JSON::toString(projectToJson(sentinel))==token,"a bad clipboard pattern rejects the whole mixed paste");
    auto ids=source;ids.clips.push_back(ids.clips[0]);ids.tracks.push_back(ids.tracks[0]);ensurePlaylistEditorIds(ids);expect(ids.clips[0].editorId!=ids.clips.back().editorId&&ids.tracks[0].editorId!=ids.tracks.back().editorId,"cloned editor identities are normalized without changing file format");auto json=projectToJson(source);expect(!JSON::toString(json).contains(source.clips[0].editorId)&&!JSON::toString(json).contains(source.tracks[0].editorId)&&(int)json["schema"]==projectSchema,"clip/channel identities remain editor-only under the current project schema");
    auto musical=source;musical.clips.resize(4);Project moved;transformPlaylistGroup(musical,{0,1,2,3},4,0,false,true,moved);auto a=render(musical,assets,root,48000),b=render(moved,assets,root,144000,127);expect(a.getMagnitude(0,0,48000)>.001f&&b.getMagnitude(0,0,96000)==0&&b.getMagnitude(0,96000,48000)>.001f,"group move shifts actual song audio by the exact requested bars");
}
